import {
    Injectable,
} from "@nestjs/common"
import {
    EntityManager,
} from "typeorm"
import {
    CodingProblemEntity,
} from "@modules/databases/postgresql/primary/entities/coding-problem.entity"
import {
    CodingSolutionRevealEntity,
} from "@modules/databases/postgresql/primary/entities/coding-solution-reveal.entity"
import {
    CodingSubmissionEntity,
} from "@modules/databases/postgresql/primary/entities/coding-submission.entity"
import {
    CodingVerdict,
} from "@modules/databases/postgresql/primary/enums/coding-verdict"
import {
    InjectPrimaryPostgreSQLEntityManager,
} from "@modules/databases/postgresql/primary/primary.decorators"
import {
    CodingProblemNotFoundException,
} from "@modules/platform/exceptions/errors/coding/coding-problem-not-found"
import {
    WinstonLog,
} from "@modules/platform/winston/enums/winston-log"
import {
    WinstonService,
} from "@modules/platform/winston/winston.service"
import {
    EnqueueJudgeCodingSubmissionJobService,
} from "../jobs/enqueue/judge-coding-submission.service"
import {
    DeviceService,
} from "../device/device.service"
import type {
    AcceptedSubmissionSummaryRow,
    AcceptedSubmissionSummaryResult,
    GetAcceptedSubmissionSummaryParams,
    ListMyCodingSubmissionsParams,
    ListMyCodingSubmissionsResult,
    RecordSolutionRevealParams,
    RecordSolutionRevealResult,
    SubmitCodingSolutionParams,
    SubmitCodingSolutionResult,
} from "./types"

/** Default page size for submission history. */
const DEFAULT_PAGE_SIZE = 20

@Injectable()
/**
 * Write-side + history business logic for coding submissions: persist a new
 * submission in `pending` state and enqueue the async judging job, and page a
 * user's submission history for a problem.
 */
export class CodingSubmissionService {
    constructor(
        @InjectPrimaryPostgreSQLEntityManager()
        private readonly entityManager: EntityManager,
        private readonly enqueueJudgeCodingSubmissionJobService: EnqueueJudgeCodingSubmissionJobService,
        private readonly deviceService: DeviceService,
        private readonly winstonService: WinstonService,
    ) {}

    /**
     * Create a pending submission for the problem and enqueue its judging job.
     *
     * @param params - userId, problem slug, language, source
     * @returns the created submission id + the judging job id to subscribe to
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async submit({
        userId,
        slug,
        language,
        sourceCode,
        telemetry,
        ipAddress = null,
        userAgent = null,
        fingerprint = null,
    }: SubmitCodingSolutionParams): Promise<SubmitCodingSolutionResult> {
        // resolve the target problem (must exist and be enabled)
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug -> typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // persist a fresh submission in the pending state (verdict set later by the worker)
        const submission = await this.entityManager.save(CodingSubmissionEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
                language,
                sourceCode,
                verdict: CodingVerdict.Pending,
                // request metadata captured for device tracking below
                ipAddress,
                userAgent,
                deviceFingerprint: fingerprint,
            })
        // best-effort: remember the device this submission came from. The
        // submission row already exists at this point, so a failure here
        // must be swallowed (logged, not thrown) -- otherwise it would strand
        // an already-persisted Pending submission with no judging job ever
        // enqueued for it.
        try {
            await this.deviceService.recordDevice({
                userId,
                fingerprint,
                ipAddress,
                userAgent,
            })
        } catch (error) {
            const cause = error instanceof Error ? error : new Error(String(error))
            this.winstonService.log(WinstonLog.BestEffortOperationFailed,
                {
                    op: "coding.device-record.failed",
                    userId,
                    referenceId: submission.id,
                    error: cause.message,
                })
        }
        // enqueue the async judging job; the returned job id is what the client subscribes to
        const job = await this.enqueueJudgeCodingSubmissionJobService.enqueue({
            userId,
            codingSubmissionId: submission.id,
        })
        // hand back both ids so the resolver can return them to the client
        return {
            submissionId: submission.id,
            jobId: job.id,
        }
    }

    /**
     * Record that the user revealed a problem's reference solution. Idempotent
     * (one row per user+problem). Once recorded, a later first solve of that
     * problem awards no points -- peeking the answer forfeits the score.
     *
     * @param params - the viewing user's id + the problem slug
     * @returns whether a new reveal row was created (false when already revealed)
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async recordSolutionReveal({
        userId,
        slug,
    }: RecordSolutionRevealParams): Promise<RecordSolutionRevealResult> {
        // resolve the target problem (must exist + be enabled) and load its reference
        // solutions -- this gated mutation is the ONLY place they are served to the client
        // (the problem detail read never carries them: not a GraphQL field, not indexed).
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
                relations: {
                    solutions: true,
                },
            })
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        const solutions = problem.solutions ?? []
        // already revealed -> idempotent: skip re-recording but still serve the answer
        const existing = await this.entityManager.findOne(CodingSolutionRevealEntity,
            {
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
            })
        if (existing) {
            return {
                revealed: false,
                solutions,
            }
        }
        // first reveal -> persist the forfeit marker
        await this.entityManager.save(CodingSolutionRevealEntity,
            {
                user: {
                    id: userId,
                },
                problem: {
                    id: problem.id,
                },
            })
        return {
            revealed: true,
            solutions,
        }
    }

    /**
     * Page a user's submissions for one problem, newest first.
     *
     * @param params - userId, slug, pagination
     * @returns the page of submissions + total count
     * @throws CodingProblemNotFoundException when the slug is unknown/disabled
     */
    async listMine({
        userId,
        slug,
        page = 1,
        limit = DEFAULT_PAGE_SIZE,
    }: ListMyCodingSubmissionsParams): Promise<ListMyCodingSubmissionsResult> {
        // resolve the problem id from the slug
        const problem = await this.entityManager.findOne(CodingProblemEntity,
            {
                where: {
                    slug,
                    enabled: true,
                },
            })
        // unknown/disabled slug -> typed not-found
        if (!problem) {
            throw new CodingProblemNotFoundException({
                identifier: slug,
            })
        }
        // page the user's submissions for this problem, newest first
        const [submissions,
            total] = await this.entityManager.findAndCount(
            CodingSubmissionEntity,
            {
                // filter by the RELATION properties, not the read-only @RelationId
                // virtual columns (`userId`/`codingProblemId` aren't queryable and
                // throw EntityPropertyNotFoundError).
                where: {
                    user: {
                        id: userId,
                    },
                    problem: {
                        id: problem.id,
                    },
                },
                order: {
                    createdAt: "DESC",
                },
                skip: (page - 1) * limit,
                take: limit,
            },
        )
        return {
            submissions,
            total,
        }
    }

    /**
     * Read a target user's accepted-submission summary for one problem -- the
     * language(s) used across ALL accepted attempts, plus the testcase counts
     * and first-solve time from the EARLIEST accepted attempt. Backs the
     * public profile's `userCodingProblemDetail` read; deliberately hand-rolled
     * (never returns a raw {@link CodingSubmissionEntity}) so `sourceCode` /
     * `perCaseResults` / reference solutions can never leak through it.
     *
     * @param params - {@link GetAcceptedSubmissionSummaryParams}
     * @returns the summary, or null when the target user has no accepted submission for the problem
     */
    async getAcceptedSummary(
        {
            userId,
            problemId,
        }: GetAcceptedSubmissionSummaryParams,
    ): Promise<AcceptedSubmissionSummaryResult | null> {
        const rows = await this.entityManager.query<Array<AcceptedSubmissionSummaryRow>>(
            `
            WITH accepted AS (
                SELECT language, passed_count, total_count, created_at
                FROM coding_submissions
                WHERE user_id = $1 AND coding_problem_id = $2 AND verdict = 'accepted'
            )
            SELECT
                (SELECT array_agg(DISTINCT language::text) FROM accepted) AS languages,
                (SELECT passed_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS passed_count,
                (SELECT total_count FROM accepted ORDER BY created_at ASC LIMIT 1) AS total_count,
                (SELECT MIN(created_at) FROM accepted) AS first_solved_at
            `,
            [
                userId,
                problemId,
            ],
        )
        const row = rows[0]
        // no accepted attempt for this user+problem -> nothing to show
        if (!row?.first_solved_at) {
            return null
        }
        return {
            languages: row.languages ?? [],
            verdict: CodingVerdict.Accepted,
            passedCount: Number(row.passed_count) || 0,
            totalCount: Number(row.total_count) || 0,
            firstSolvedAt: row.first_solved_at,
        }
    }
}

import type {
    DataSource,
    QueryRunner,
} from "typeorm"
import type {
    QueryResultCache,
} from "typeorm/cache/QueryResultCache"
import type {
    QueryResultCacheOptions,
} from "typeorm/cache/QueryResultCacheOptions"

/**
 * Process-local, in-memory implementation of TypeORM's {@link QueryResultCache}.
 *
 * Wired into the primary DataSource via `cache.provider` so any query that opts
 * in with `{ cache: { id, milliseconds } }` is served from a plain `Map`
 * instead of the default `query-result-cache` table (database) or Redis.
 *
 * Trade-offs (acceptable for small, hot, rarely-changing catalogs like
 * `ai_models`):
 * - **Per-instance** -- each pod keeps its own copy; entries expire by TTL, so
 *   staleness is bounded by the query's `milliseconds`.
 * - **No eviction cap** -- fine because the keyspace is a handful of stable
 *   `identifier`s; never cache unbounded user-supplied keys here.
 */
export class InMemoryQueryResultCache implements QueryResultCache {
    /** identifier (or raw query) -> last stored cache entry. */
    private readonly store = new Map<string, QueryResultCacheOptions>()

    constructor(
        private readonly dataSource: DataSource,
    ) { }

    /** No external connection -- the cache lives in this process's heap. */
    async connect(): Promise<void> {
        // intentionally empty -- nothing to connect to
    }

    /** Drop every entry when the DataSource disconnects. */
    async disconnect(): Promise<void> {
        this.store.clear()
    }

    /** No schema to provision for an in-memory map. */
    async synchronize(): Promise<void> {
        // intentionally empty -- no backing table
    }

    /**
     * Look an entry up by its `identifier` (preferred) or raw `query` text.
     * @returns the stored entry, or `undefined` on miss.
     */
    async getFromCache(
        options: QueryResultCacheOptions,
    ): Promise<QueryResultCacheOptions | undefined> {
        const key = this.resolveKey(options)
        if (!key) {
            return undefined
        }
        return this.store.get(key)
    }

    /**
     * Persist a freshly executed query result under its key.
     * @param options - the new cache entry (carries `result`, `time`, `duration`).
     */
    async storeInCache(
        options: QueryResultCacheOptions,
    ): Promise<void> {
        const key = this.resolveKey(options)
        if (!key) {
            return
        }
        this.store.set(
            key,
            options,
        )
    }

    /**
     * TTL check used by TypeORM to decide between cache hit and re-query.
     * @returns `true` when `time + duration` is already in the past.
     */
    isExpired(
        savedCache: QueryResultCacheOptions,
    ): boolean {
        const createdAt = savedCache.time ?? 0
        return createdAt + savedCache.duration < Date.now()
    }

    /** Flush the entire cache. */
    async clear(): Promise<void> {
        this.store.clear()
    }

    /**
     * Invalidate specific entries by identifier (e.g. after a catalog reseed).
     * @param identifiers - cache `id`s to drop.
     */
    async remove(
        identifiers: Array<string>,
    ): Promise<void> {
        for (const identifier of identifiers) {
            this.store.delete(identifier)
        }
    }

    /** Prefer the user-set `identifier`; fall back to the raw query text. */
    private resolveKey(
        options: QueryResultCacheOptions,
    ): string | undefined {
        return options.identifier ?? options.query
    }
}

import {
    MigrationInterface,
    QueryRunner,
} from "typeorm"
import {
    IrreversibleMigrationException,
} from "@modules/platform/exceptions/errors/migrations/irreversible-migration"

/**
 * Drops the four AI Lab EVAL tables -- the graded prompt-challenge feature that
 * sat alongside (but is distinct from) the AI Lab Playground. The eval feature
 * has been removed from the codebase (services, resolvers, entities, processor
 * pipeline, queue), so its tables are dropped here.
 *
 * Tables dropped (children before parents to respect FK constraints):
 * - `ai_lab_eval_case_results` -- per-case grading result (FK -> runs, cases)
 * - `ai_lab_eval_runs`         -- one graded submission (FK -> sets)
 * - `ai_lab_eval_cases`        -- one input + scoring metric (FK -> sets)
 * - `ai_lab_eval_sets`         -- the eval set (rubric + threshold), the parent
 *
 * Dev runs schema via TypeORM `synchronize` (which will itself drop the tables
 * once the entities are gone); this migration applies the same change where
 * `synchronize` is disabled (prod). Idempotent (`DROP TABLE IF EXISTS`).
 *
 * The Playground tables (`ai_lab_playgrounds`, `ai_lab_playground_translations`,
 * `ai_lab_runs`) are intentionally left untouched.
 */
export class DropAiLabEvalTables1726100000000 implements MigrationInterface {
    /** Stable name surfaced in the TypeORM migrations table. */
    name = "DropAiLabEvalTables1726100000000"

    /**
     * Forward migration: drop the four eval tables, children before parents so
     * the foreign-key constraints do not block the drop.
     *
     * @param queryRunner - Active TypeORM query runner bound to the transaction.
     */
    async up(queryRunner: QueryRunner): Promise<void> {
        await queryRunner.query(`
            DROP TABLE IF EXISTS "ai_lab_eval_case_results";
        `)
        await queryRunner.query(`
            DROP TABLE IF EXISTS "ai_lab_eval_runs";
        `)
        await queryRunner.query(`
            DROP TABLE IF EXISTS "ai_lab_eval_cases";
        `)
        await queryRunner.query(`
            DROP TABLE IF EXISTS "ai_lab_eval_sets";
        `)
    }

    /**
     * Reverse migration: not supported. The eval feature has been removed from
     * the codebase, so there are no entities to recreate these tables from, and
     * dropping-then-recreating would in any case lose every graded submission.
     *
     * @param _queryRunner - Active TypeORM query runner (unused).
     * @throws Always -- this migration is not reversible.
     */
    async down(_queryRunner: QueryRunner): Promise<void> {
        throw new IrreversibleMigrationException({
            migrationName: "DropAiLabEvalTables1726100000000",
            reason: "the AI Lab eval feature has been removed and its data cannot be restored.",
        })
    }
}

import {
    Injectable,
} from "@nestjs/common"
import {
    DeepPartial,
} from "typeorm"
import {
    HeadhuntingCompanyTranslationEntity,
} from "@modules/databases/postgresql/primary/entities/headhunting-company-translation.entity"
import {
    HeadhuntingCompanyEntity,
} from "@modules/databases/postgresql/primary/entities/headhunting-company.entity"
import {
    UpsertService,
} from "../../shared/upsert/upsert.service"

@Injectable()
/**
 * Upserts one headhunting company + `headhunting_company_translations`. Child
 * consultants are NOT written here -- {@link ConsultantInsertService} runs after
 * the company row exists so the FK is valid.
 */
export class HeadhuntingCompanyInsertService {
    constructor(
        private readonly upsertService: UpsertService,
    ) {}

    async insert(
        company: DeepPartial<HeadhuntingCompanyEntity>,
    ): Promise<void> {
        const companyId = company.id as string
        const {
            translations,
            consultants,
            ...rest
        } = company
        await this.upsertService.upsertMany(
            HeadhuntingCompanyEntity,
            [rest],
        )
        if (translations) {
            await this.upsertService.upsertTranslationMany(
                HeadhuntingCompanyTranslationEntity,
                translations,
                {
                    companyId,
                },
            )
        }
    }
}

